import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { Component, Inject, OnInit } from '@angular/core';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { AssignparticipantComponent } from '../assignparticipant/assignparticipant.component';
import { NewserverComponent } from '../newserver/newserver.component';
import { SessionService } from '../../services'; 
import { HttpClientModule } from '@angular/common/http';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatCheckboxModule } from '@angular/material/checkbox';

@Component({
  selector: 'app-assignservers',
  standalone: true,
  providers: [SessionService],
  imports: [ButtonComponent, IconComponent, FormsModule, MatTooltipModule, MatCheckboxModule, CommonModule, ReactiveFormsModule, HttpClientModule, TranslateModule],
  templateUrl: './assignservers.component.html',
  styleUrl: './assignservers.component.scss'
})
export class AssignserversComponent implements OnInit {
  servers: any = []
  permission: string = 'N';
  constructor(private readonly dialog: MatDialog, public sessionService: SessionService, private readonly dialogRefs: MatDialogRef<AssignserversComponent>, @Inject(MAT_DIALOG_DATA) public data: any) { }

  ngOnInit(): void {
    this.getServers();
  }


  async getServers() {
    let data: any = await this.sessionService.serverList();
    if (data && data.length > 0) {
      this.servers = data;
      if (this.data.permission == 'E') {
        this.permission = 'E';
      }
    }
  }

  assign(x) {
    const dialogRef = this.dialog.open(AssignparticipantComponent,
      {
        width: '630px',
        height: 'fit-content',
        data: { server: x, session: this.data }
      });

    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.dialogRefs.close(true)
      }
    });
  }

  newservers() {

    const dialogRef = this.dialog.open(NewserverComponent,
      {
        width: '600px',
        height: 'fit-content'
      });

    dialogRef.afterClosed().subscribe(result => {

      this.getServers();
    });
  }

  async chooseServer(x) {

    let data: any = await this.sessionService.setServer(this.data.nSesid, x.nRTSid);

    if (data.length > 0) {
      this.sessionService.show(data[0]["value"])
      this.dialogRefs.close(true)
    }
  }

  async assignServer(x) {
    let mdl: any = {
      nCaseid: this.data.nCaseid,
      nSesid: this.data.nSesid,
      nRTSid: x.nRTSid,
      cNotifytype: 'O', //this.isOndate ? 'O' : 'N',
      jUserid: JSON.stringify([])
    }
    let res = await this.sessionService.assignUser(mdl);
    if (res) {
      this.dialogRefs.close(true)
    }
  }

  trackByFn(index: number, item: any): any {
    return item.nRTSid;
  }

}
