import { Component, Inject } from '@angular/core';
 
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, FormsModule } from '@angular/forms';
import { SessionService } from '../../services/session/session.service'; 
import { HttpClientModule } from '@angular/common/http';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { TranslateModule } from '@ngx-translate/core';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-newserver',
  standalone: true,
  providers: [SessionService],
  imports: [ButtonComponent, FormsModule, MatTooltipModule, MatCheckboxModule, CommonModule, ReactiveFormsModule, HttpClientModule, TranslateModule],
  templateUrl: './newserver.component.html',
  styleUrl: './newserver.component.scss'
})
export class NewserverComponent {
  frm: FormGroup;
  formsubmit: boolean = false;
  isLoading: boolean = false;
  nUserid:any
  userInfo:any={}
  constructor(private formBuilder: FormBuilder, public sessionService: SessionService, private dialogRef: MatDialogRef<NewserverComponent>, @Inject(MAT_DIALOG_DATA) public data: any,private ss: SecureStorageService) {
    this.frm = this.formBuilder.group({
      nRTSid: [0],
      cUrl: ['', [Validators.required]],
      nPort: ['', [Validators.required]],
      cName: ['', [Validators.required]],
      permission: ['N']
    });
  }

  async ngOnInit() {
    this.userInfo =  await this.ss.getUserInfo();
    this.nUserid = this.userInfo.nUserid;
  }


  submit() {
    this.formsubmit = true;
    if (this.frm.invalid) {
      return;
    }

    this.isLoading = true;

    const mdl = { ...this.frm.value, nUserid: this.nUserid };

    this.sessionService.addServer(mdl).then((data) => {
      this.isLoading = false;
      this.dialogRef.close();
    }).catch((err) => {
      this.isLoading = false;
    })

  }

  close() {
    this.dialogRef.close();
  }

}
